before:
Complete local Go example; the app itself does not execute it:
```go
package main

import (
"fmt"
)


func main() {
    values := make(chan int, 1)
    values <- 5
    select {
    case value := <-values: fmt.Println(value)
    default: fmt.Println("not ready")
    }
}
```

